private let mojoBuiltins: [String: ILType] = [
    /// Profiles declare this method, a wrapper method around `getRemote` that follows
    /// the Singleton pattern, in `codePrefix`. This method ensures: (1) `getRemote`
    /// is only called once, and (2) the remote is saved to a global variable so it
    /// can be closed at the end of the program.
    "getOrCreatePrimaryRemote": .function([] => .jsBlinkMojomFileSystemAccessManagerRemote),
    /// Declared in `codePrefix`. `MojoAsyncFunctionGenerator` pushes the promise
    /// of every async function it emits, and `codeSuffix` awaits them all. Typed
    /// as an opaque object Fuzzilli does not use it as a general-purpose array.
    "mojoAsyncFunctionPromises": .object(withMethods: ["push"]),
    "blink.mojom.FileSystemAccessDirectoryHandleRemote":
       .constructor([] => .jsBlinkMojomFileSystemAccessDirectoryHandleRemote),
    "blink.mojom.FileSystemAccessFileHandleRemote":
       .constructor([] => .jsBlinkMojomFileSystemAccessFileHandleRemote),
    "blink.mojom.BlobRemote":
       .constructor([] => .jsBlinkMojomBlobRemote),
    "network.mojom.DataPipeGetterRemote":
       .constructor([] => .jsNetworkMojomDataPipeGetterRemote),
    "network.mojom.URLLoaderRemote":
       .constructor([] => .jsNetworkMojomURLLoaderRemote),
    "blink.mojom.FileSystemAccessTransferTokenRemote":
       .constructor([] => .jsBlinkMojomFileSystemAccessTransferTokenRemote),
    "blink.mojom.FileSystemAccessObserverHostRemote":
       .constructor([] => .jsBlinkMojomFileSystemAccessObserverHostRemote),
    "blink.mojom.BlobReaderClientCallbackRouter":
       .constructor([] => .jsBlinkMojomBlobReaderClientCallbackRouter),
    "network.mojom.URLLoaderClientCallbackRouter":
